// Plain-text translations only. Callers must escape strings used in HTML.
const PARTNER_LOCALES = Object.freeze([
  {code:'en',label:'English',htmlLang:'en',dir:'ltr'},
  {code:'he',label:'עברית',htmlLang:'he',dir:'rtl'},
  {code:'pl',label:'Polski',htmlLang:'pl',dir:'ltr'},
  {code:'de',label:'Deutsch',htmlLang:'de',dir:'ltr'},
  {code:'fr',label:'Français',htmlLang:'fr',dir:'ltr'},
  {code:'it',label:'Italiano',htmlLang:'it',dir:'ltr'},
  {code:'nl',label:'Nederlands',htmlLang:'nl',dir:'ltr'},
  {code:'es',label:'Español',htmlLang:'es',dir:'ltr'},
  {code:'sv',label:'Svenska',htmlLang:'sv',dir:'ltr'},
  {code:'cs',label:'Čeština',htmlLang:'cs',dir:'ltr'},
  {code:'zh',label:'繁體中文',htmlLang:'zh-Hant',dir:'ltr'},
  {code:'ko',label:'한국어',htmlLang:'ko',dir:'ltr'},
].map(Object.freeze));

function partnerLocale(input) {
  const code = String(input || '').trim().toLowerCase().replaceAll('_', '-').split('-')[0];
  return PARTNER_LOCALES.some(locale => locale.code === code) ? code : 'en';
}

const normalize = value => String(value).replace(/\s+/gu, ' ').trim();
const catalog = Object.fromEntries(PARTNER_LOCALES.map(({code}) => [code, Object.create(null)]));
function add(key, translations) {
  catalog.en[normalize(key)] = key;
  if (translations.length !== PARTNER_LOCALES.length - 1) throw new Error('Incomplete partner translation: ' + key);
  PARTNER_LOCALES.slice(1).forEach(({code}, index) => { catalog[code][normalize(key)] = translations[index]; });
}

