// Typographic variants share translations without weakening exact key lookup.
for (const [variant, original] of [
 ['Checking availability…', 'Checking availability.'],
 ['Requested country editions — select 1 to 25', 'Requested country editions - select 1 to 25'],
 ['Relevant software categories — select at least one', 'Relevant software categories - select at least one'],
 ['Continue to PayPal Sandbox — test only', 'Continue to PayPal Sandbox - test only'],
 ['Official source URLs — sandbox test', 'Official source URLs - sandbox test'],
 ['Submitting your application…', 'Submitting your application.'],
 ['Checking the payment with the payment service…', 'Checking the payment with the payment service.'],
 ['Preparing the approved payment…', 'Preparing the approved payment.'],
 ['Eligible — awaiting agreed terms', 'Eligible - awaiting agreed terms'],
 ['Approved — awaiting payment', 'Approved - awaiting payment'],
 ['Payment verified — provide official sources', 'Payment verified - provide official sources'],
 ['Sources received — editorial research pending', 'Sources received - editorial research pending'],
 ['Scheduled — no renewal charge', 'Scheduled - no renewal charge'],
]) {
 for (const {code} of PARTNER_LOCALES) catalog[code][normalize(variant)] = code === 'en' ? variant : catalog[code][normalize(original)];
}
for (const {code} of PARTNER_LOCALES) catalog[code]['Payment status: {status}'] = catalog[code]['Payment status: {status}.'].replace(/[.。]$/u, '');

const PARTNER_MESSAGES = Object.freeze(Object.fromEntries(Object.entries(catalog).map(([code, messages]) => [code, Object.freeze(messages)])));
function partnerUiText(locale, key, params = {}) {
  const dictionary = PARTNER_MESSAGES[partnerLocale(locale)];
  const normalized = normalize(key);
  const value = Object.hasOwn(dictionary, normalized) ? dictionary[normalized] : (PARTNER_MESSAGES.en[normalized] ?? String(key));
  return value.replace(/\{([a-zA-Z][a-zA-Z0-9_]*)\}/g, (token, name) => Object.hasOwn(params, name) ? String(params[name]) : token);
}


function scPartnerCategoryCompanies(companies) {
 if (!Array.isArray(companies) || companies.length < 5 || companies.length > 20) throw new Error('Provide between 5 and 20 distinct companies with official websites.');
 const names=new Set(),hosts=new Set();
 return companies.map(company=>{
  const name=String(company.name||'').trim(),website=String(company.website||'').trim();let url;
  try{url=new URL(website);}catch{throw new Error('Every company needs a valid HTTPS official website.');}
  if(!name||name.length>200||url.protocol!=='https:'||url.username||url.password||url.port)throw new Error('Every company needs a name and a public HTTPS official website without credentials or a custom port.');
  const key=name.normalize('NFKC').toLocaleLowerCase('en').replace(/[^\p{L}\p{N}]/gu,''),hostname=url.hostname.toLowerCase().replace(/^www\./,''),labels=hostname.split('.'),countrySuffix=labels.at(-1).length===2&&['co','com','org','net','gov','ac','edu'].includes(labels.at(-2)),host=labels.slice(countrySuffix?-3:-2).join('.');
  if(names.has(key)||hosts.has(host))throw new Error('Use distinct company names and distinct official website domains.');
  names.add(key);hosts.add(host);return {name,website:url.href};
 });
}
function scPartnerQuoteInput(service,fields,tax,expires,approvedMarkets,requestedMarkets) {
 const pricing=scPartnerCountryPrice(service,approvedMarkets,requestedMarkets);
 if(!service||service.currency!=='USD'||!fields.scope||!fields.deliverable||!Number.isFinite(Date.parse(expires)))throw new Error('Verify the service, scope, deliverable and expiry before issuing a proposal.');
 if(service.code==='legacy_registration'){
  if(!Number.isSafeInteger(service.baseMinor)||Object.values(fields).some(value=>!value)||!/^\d+(?:\.\d{1,2})?$/.test(tax))throw new Error('Complete the previously agreed commercial terms and tax amount.');
  const [whole,fraction='']=tax.split('.'),taxMinor=Number(whole)*100+Number(fraction.padEnd(2,'0'));
  if(!Number.isSafeInteger(taxMinor)||taxMinor>service.baseMinor)throw new Error('Enter the valid previously agreed tax amount.');
  return {...fields,approvedMarkets:[...approvedMarkets],serviceCode:service.code,baseMinor:service.baseMinor,taxMinor,currency:service.currency,expiresAt:new Date(expires).toISOString()};
 }
 const terms=service.standardTerms,required=['termsVersion','deliveryPeriod','taxTreatment','cancellationRefunds','updatesAndDuration'];
 if(!Number.isSafeInteger(service.totalMinor)||service.totalMinor<=0||service.taxIncluded!==true||service.taxItemized!==false||!terms||required.some(key=>typeof terms[key]!=='string'||!terms[key]))throw new Error('The approved service price and terms could not be verified. Refresh before issuing a proposal.');
 if(tax!=='')throw new Error('The final service price includes taxes. Do not add a separate tax amount.');
 return {scope:fields.scope,deliverable:fields.deliverable,...Object.fromEntries(required.map(key=>[key,terms[key]])),approvedMarkets:[...approvedMarkets],serviceCode:service.code,pricePolicyVersion:service.pricePolicyVersion||service.policyVersion,baseMinor:service.baseMinor,totalMinor:pricing.totalMinor,taxIncluded:true,taxItemized:false,currency:service.currency,expiresAt:new Date(expires).toISOString()};
}
function scPartnerCountryPrice(service,approvedMarkets,requestedMarkets) {
 if(!service||!Array.isArray(approvedMarkets)||!approvedMarkets.length||!Array.isArray(requestedMarkets)||new Set(approvedMarkets).size!==approvedMarkets.length||approvedMarkets.some(market=>!requestedMarkets.includes(market)))throw new Error('Select at least one requested country edition for this quote.');
 const additionalCountryCount=service.includedCountryCount===1?approvedMarkets.length-1:0,additionalCountryMinor=service.includedCountryCount===1?service.additionalCountryMinor:0;
 if(!Number.isSafeInteger(service.baseMinor)||!Number.isSafeInteger(additionalCountryMinor)||additionalCountryMinor<0)throw new Error('The approved service price could not be verified.');
 return {baseMinor:service.baseMinor,additionalCountryCount,additionalCountryMinor,additionalMinor:additionalCountryCount*additionalCountryMinor,totalMinor:service.baseMinor+additionalCountryCount*additionalCountryMinor};
}
function scPartnerQuoteAmounts(quote,locale='en-US') {
 const money=amount=>new Intl.NumberFormat(locale,{style:'currency',currency:'USD'}).format(Number(amount)/100);
 if(quote.taxIncluded===true&&quote.taxItemized===false){
  const breakdown=quote.includedCountryCount===1&&Number.isSafeInteger(quote.additionalMinor)&&Number.isSafeInteger(quote.additionalCountryCount)
   ? [['Base fee (one country edition)',money(quote.baseMinor)],['Additional country editions',String(quote.additionalCountryCount)],['Additional country fee',money(quote.additionalMinor)]]:[];
  return [...breakdown,['Total due (taxes included)',money(quote.totalMinor)],['Tax detail','Taxes are included. A separate tax breakdown is not itemized.']];
 }
 return [['Base fee',money(quote.baseMinor)],['Tax amount',money(quote.taxMinor)],['Total due',money(quote.totalMinor)]];
}
function scPartnerCanInvite(application,quote,payment,environment,now=Date.now()) {
 if(!['sandbox','live'].includes(environment))return false;
 const paid=payment?.state==='paid'&&payment.environment===environment&&['paid_awaiting_onboarding','needs_information','onboarding_received','editorial_review','ready_to_publish','published','research_failed'].includes(application.status);
 return paid||(application.status==='approved_awaiting_payment'&&quote?.paymentEnvironment===environment&&Date.parse(quote.expiresAt)>now);
}
function scPartnerApprovalEmailRequest(application, approvalEmail, confirmed) {
 if (!confirmed) throw new Error('Confirm the recipient and replacement of any unused invitation.');
 if (['pending','retry','checking','dispatching','manual_review'].includes(approvalEmail?.state)) throw new Error('Reconcile the current invitation before requesting a replacement.');
 return { expectedVersion: application.version, renew: approvalEmail?.state === 'expired' || !!approvalEmail?.acceptedAt };
}
function scPartnerApprovalOutcome(result) {
 if (result.application?.status !== 'approved_awaiting_payment') return 'Eligibility decision saved. No new invitation was sent by this decision.';
 const mail=result.approvalEmail,diagnostic=mail?.lastCode?' Diagnostic: '+mail.lastCode+'.':'';
 if (mail?.state==='accepted') return 'Approved. The email service accepted the invitation to the applicant. Inbox delivery and email opening are not verified.';
 if (['pending','retry','checking','dispatching'].includes(mail?.state)) return 'Approved. Invitation status: '+mail.state+'. A safe retry or status check is pending; do not create another invitation.'+diagnostic;
 return 'Approved with a service offer, but invitation email is NOT confirmed. Status: '+(mail?.state||'not_queued')+'. Check the email section before contacting the applicant.'+diagnostic;
}
function scPartnerPaymentDestination(payment) {
 if (!payment || typeof payment !== 'object') throw new Error('The payment response could not be verified. Contact the publisher.');
 if (typeof payment.approveUrl !== 'string') {
  if (typeof payment.paymentState === 'string' && typeof payment.paid === 'boolean') return null;
  throw new Error('The payment response could not be verified. Contact the publisher.');
 }
 const url = new URL(payment.approveUrl);
 if (url.protocol !== 'https:' || !['www.paypal.com', 'www.sandbox.paypal.com'].includes(url.hostname) || url.port || url.username || url.password) throw new Error('The payment destination could not be verified. Contact the publisher.');
 return url.href;
}
