 const node=(tag,text,attributes={},literal=false)=>{const element=document.createElement(tag);if(text!==undefined&&text!==null)element.textContent=literal?String(text):t(text);for(const [key,value]of Object.entries(attributes))element.setAttribute(key,String(value));return element;};
