  for(const kind of ['publication','review-complete'])$('#partner-'+kind).addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const lines=name=>readForm(form,name).split(/\r?\n/).map(item=>item.trim()).filter(Boolean),reviewedAt=readForm(form,'reviewedAt');if(!/(?:Z|[+-]\d{2}:\d{2})$/.test(reviewedAt)||!Number.isFinite(Date.parse(reviewedAt)))return visibleFormError('Enter a valid review completion date and time including its timezone.');const body={expectedVersion:selected.application.version,listingUrls:lines('listingUrls'),evidenceUrls:lines('evidenceUrls'),reviewedAt:new Date(reviewedAt).toISOString(),reason:readForm(form,'reason'),publicationVerified:checked(form,'publicationVerified'),publicSourcesChecked:checked(form,'publicSourcesChecked')};busy(form.querySelector('[type=submit]'),async()=>{const id=selected.application.id;await api(actionPath(kind),{body,csrf});await reloadSelected(id);message(kind==='publication'?'Verified publication recorded and included review scheduled. No website was changed by this action.':'Included review recorded at no charge. The next six-month review date is shown above.');});});

