   if(['approve','requote'].includes(decision)){if(!quoteIssuingEnabled||!['approve','requote'].includes(decision))return visibleFormError('Commercial terms must be enabled before issuing an approved service proposal.');const fields=['scope','deliverable','deliveryPeriod','taxTreatment','cancellationRefunds','updatesAndDuration','termsVersion'],quote=Object.fromEntries(fields.map(name=>[name,readForm(review,name)])),tax=readForm(review,'taxAmount'),expires=readForm(review,'expiresAt');try{body.quote=scPartnerQuoteInput(selected.application.service||serviceCatalog.find(item=>item.code===(selected.application.serviceCode||'supplier_registration')),quote,tax,expires,values(review,'approvedMarkets'),selected.application.markets);}catch(error){return visibleFormError(error.message);}}
   if(['approve','requote'].includes(decision)){body.categoryEvidenceChecked=checked(review,'categoryEvidenceChecked');body.distinctCompaniesChecked=checked(review,'distinctCompaniesChecked');body.rescanEligibilityChecked=checked(review,'rescanEligibilityChecked');body.legacyListingVerified=checked(review,'legacyListingVerified');if(readForm(review,'parentApplicationId'))body.parentApplicationId=readForm(review,'parentApplicationId');if(selected.application.serviceCode==='category_registration'&&(!body.categoryEvidenceChecked||!body.distinctCompaniesChecked))return visibleFormError('Complete both category eligibility checks.');if(selected.application.serviceCode==='supplier_rescan'&&!body.rescanEligibilityChecked)return visibleFormError('Verify the existing listing and rescan eligibility first.');}
